const j = $json || {};
const body = (j.body && typeof j.body === 'object') ? j.body : null;
const src = body || j;
const system = String(src.system || 'You are a helpful assistant.');
const user = String(src.user || '');
let mt = src.max_tokens;
const maxTokens = (mt !== undefined && mt !== null && String(mt).length) ? Number(mt) : 1200;
let tp = src.temperature;
const temperature = (tp !== undefined && tp !== null && String(tp).length) ? Number(tp) : 0.6;
const task_type = String(src.task_type || 'chat').toLowerCase();
const provider = String(src.provider || '');
return [{ json: { system: system, user: user, max_tokens: maxTokens, temperature: temperature, task_type: task_type, provider: provider } }];

const j = $('Normalize Input').first().json || {};
const p = String(j.provider || '').toLowerCase();
const known = ['groq', 'openrouter', 'zai'];
const ok = known.indexOf(p) !== -1;
return [{ json: { ok: true, action: 'reorder', provider: p, applied: ok, note: ok ? (p + ' demoted to end of fallback order') : ('unknown provider: ' + p + ' - no-op'), text: '', provider_used: 'none' } }];

const inp = $('Normalize Input').first().json || {};
let usage = [];
try { usage = $('Get Recent Usage').all(); } catch (e) { usage = []; }
let health = [];
try { health = $('Get Provider Health').all(); } catch (e) { health = []; }
const now = Date.now();
const DAY = 24 * 60 * 60 * 1000;
function fails(prov) {
  let c = 0;
  for (let i = 0; i < usage.length; i++) {
    const r = usage[i].json || {};
    if (String(r.provider || '').toLowerCase() === prov && r.success === false) {
      let t = now;
      if (r.log_timestamp) { const parsed = new Date(r.log_timestamp).getTime(); if (!isNaN(parsed)) t = parsed; }
      if (now - t <= DAY) c++;
    }
  }
  return c;
}
function healthDemoted(prov) {
  for (let i = 0; i < health.length; i++) {
    const r = health[i].json || {};
    if (String(r.provider || '').toLowerCase() === prov && r.demoted === true) return true;
  }
  return false;
}
const base = ['groq', 'openrouter', 'zai'];
const messages = [{ role: 'system', content: inp.system }, { role: 'user', content: inp.user }];
const groqBody = { model: 'llama-3.3-70b-versatile', temperature: inp.temperature, max_tokens: inp.max_tokens, messages: messages };
const openrouterBody = { model: 'meta-llama/llama-3.3-70b-instruct', temperature: inp.temperature, max_tokens: inp.max_tokens, messages: messages };
const zaiBody = { model: 'glm-4.5-flash', temperature: inp.temperature, max_tokens: inp.max_tokens, messages: messages };
const deepseekBody = { model: 'deepseek-chat', temperature: inp.temperature, max_tokens: inp.max_tokens, messages: messages };
const userStr = String(inp.user || '').trim();
if (!userStr) {
  return [{ json: { system: inp.system, user: inp.user, max_tokens: inp.max_tokens, temperature: inp.temperature, task_type: inp.task_type, order: [], demoted: {}, empty_input: true, attempt_groq: false, attempt_openrouter: false, attempt_zai: false, groqBody: groqBody, openrouterBody: openrouterBody, zaiBody: zaiBody, deepseekBody: deepseekBody } }];
}
const demoted = {};
for (let k = 0; k < base.length; k++) { const p = base[k]; demoted[p] = (fails(p) > 5) || healthDemoted(p); }
const active = base.filter(function (p) { return !demoted[p]; });
const inactive = base.filter(function (p) { return demoted[p]; });
let order = active.concat(inactive);
const allDemoted = active.length === 0;
if (allDemoted) { order = base.slice(); }
const attempt = {};
for (let m = 0; m < base.length; m++) { const p = base[m]; attempt[p] = allDemoted ? true : !demoted[p]; }
return [{ json: { system: inp.system, user: inp.user, max_tokens: inp.max_tokens, temperature: inp.temperature, task_type: inp.task_type, order: order, demoted: demoted, empty_input: false, attempt_groq: attempt.groq, attempt_openrouter: attempt.openrouter, attempt_zai: attempt.zai, groqBody: groqBody, openrouterBody: openrouterBody, zaiBody: zaiBody, deepseekBody: deepseekBody } }];

const src = $input.first().json || {};
let txt = '';
try { txt = src.choices[0].message.content || ''; } catch (e) { txt = ''; }
txt = String(txt).trim();
return [{ json: { text: txt, provider: 'groq', ok: txt.length > 0 } }];

const src = $input.first().json || {};
let txt = '';
try { txt = src.choices[0].message.content || ''; } catch (e) { txt = ''; }
txt = String(txt).trim();
return [{ json: { text: txt, provider: 'openrouter', ok: txt.length > 0 } }];

const src = $input.first().json || {};
let txt = '';
try { txt = src.choices[0].message.content || ''; } catch (e) { txt = ''; }
if (!txt) { try { txt = src.choices[0].message.reasoning_content || ''; } catch (e) {} }
txt = String(txt).trim();
return [{ json: { text: txt, provider: 'zai', ok: txt.length > 0 } }];

const src = $input.first().json || {};
let txt = '';
try { txt = src.choices[0].message.content || ''; } catch (e) { txt = ''; }
txt = String(txt).trim();
return [{ json: { text: txt, provider: 'deepseek', ok: txt.length > 0 } }];

function ev(label, key, j) {
  const r = j || {};
  const hasChoices = r.choices && r.choices.length > 0;
  let alive = false, detail = '';
  if (r.id || hasChoices) { alive = true; detail = 'OK'; }
  else {
    const err = r.error || r.message || r;
    if (err && typeof err === 'object') { detail = String(err.message || err.error || JSON.stringify(err)).slice(0, 160); }
    else { detail = String(err || 'No valid response').slice(0, 160); }
  }
  return { provider: key, label: label, alive: alive, detail: detail };
}
const results = [];
try { results.push(ev('Groq', 'groq', $('Ping Groq').first().json)); } catch (e) { results.push({ provider: 'groq', label: 'Groq', alive: false, detail: 'No output' }); }
try { results.push(ev('OpenRouter', 'openrouter', $('Ping OpenRouter').first().json)); } catch (e) { results.push({ provider: 'openrouter', label: 'OpenRouter', alive: false, detail: 'No output' }); }
try { results.push(ev('Z.ai', 'zai', $('Ping Z.ai').first().json)); } catch (e) { results.push({ provider: 'zai', label: 'Z.ai', alive: false, detail: 'No output' }); }
const iso = new Date().toISOString();
let aliveCount = 0;
const rows = [];
const dead = [];
const lines = ['AI Provider Health - ' + iso.slice(0, 16).replace('T', ' ') + ' UTC', ''];
for (let i = 0; i < results.length; i++) {
  const r = results[i];
  if (r.alive) aliveCount++; else dead.push(r.label);
  rows.push({ provider: r.provider, status: r.alive ? 'alive' : 'dead', demoted: !r.alive, last_checked: iso, last_success: r.alive ? iso : null });
  lines.push((r.alive ? 'OK ' : 'DEAD ') + r.label + (r.alive ? '' : ' - ' + r.detail));
}
lines.push('');
lines.push(aliveCount + '/' + results.length + ' providers alive.');
return [{ json: { summary: lines.join('\n'), dead_count: dead.length, dead_list: dead.join(', '), rows: rows } }];
